// Async function body run inside the REAL desktop app by parity.sh
// (`desktop.sh js "$(cat parity.js)"`).
//
// Runs the SAME scenario against two backends that both live in this page:
//   mock = window.__MINOTES__.modules["/src/lib/mockBackend.ts"].mockHandlers
//          (what every browser-mode journey talks to)
//   real = Tauri IPC -> Rust -> SQLite (the product)
// and returns one record per check: {id, area, op, inputs, mock, real, same}.
//
// Rules that keep the comparison honest:
//  - each check only uses titles / search tokens carrying its own tag (ZQ<id>),
//    and filters global lists down to that tag, so checks cannot cascade;
//  - results are SHAPED before comparing (contents, parent contents, positions,
//    booleans) so ids and timestamps never take part; leftover ids are masked;
//  - null and undefined are the same thing (JSON over IPC), keys are sorted;
//  - "both threw" counts as SAME; the two messages are kept for the report.
//
// Optional: set window.__PARITY_ONLY__ = "pg|bl" (regex on check ids) first.

const M = window.__MINOTES__ && window.__MINOTES__.modules;
if (!M || !M["/src/lib/mockBackend.ts"]) throw new Error("this build does not expose __MINOTES__.modules");
const handlers = M["/src/lib/mockBackend.ts"].mockHandlers;
const clone = v => (v === undefined ? null : JSON.parse(JSON.stringify(v)));

const NO_HANDLER = "<<no mock handler: api.ts returns undefined>>";
const backends = {
  // Same contract as api.ts invoke() in browser mode: missing handler -> undefined
  // (plus a console.warn), thrown Error -> its message.
  mock: async (cmd, args) => {
    const h = handlers[cmd];
    if (!h) return NO_HANDLER;
    try { return clone(h(clone(args || {}))); } catch (e) { throw (e && e.message) || String(e); }
  },
  real: async (cmd, args) => clone(await window.__TAURI_INTERNALS__.invoke(cmd, args || {})),
};

const GHOST = "00000000-0000-4000-8000-00000000dead"; // well-formed id that never exists
const GARBAGE = "not-a-uuid";
const uuid = () => crypto.randomUUID();

function mkB(name, id) {
  const raw = backends[name];
  const B = { name, tag: "ZQ" + id };
  B.call = (cmd, args) => raw(cmd, args);
  // t(): never throws; {ok: value} | {err: message}
  B.t = async (cmd, args) => { try { return { ok: await raw(cmd, args) }; } catch (e) { return { err: String((e && e.message) || e) }; } };
  B.n = s => B.tag + " " + s;                       // unique page/folder title
  B.w = s => ("zq" + id + s).toLowerCase();         // unique search token
  B.mine = (arr, key) => (Array.isArray(arr) ? arr.filter(x => String(x[key || "title"] || "").includes(B.tag)) : arr);
  B.page = title => raw("create_page", { title: B.n(title) });
  B.blk = (pageId, content, parentId) => raw("create_block", { pageId, content, parentId });
  // outline as [{c, parent, pos}] in the order the backend returns it
  B.tree = async pid => {
    const r = await B.t("get_page_tree", { titleOrId: pid });
    if (r.err) return r;
    const by = new Map(r.ok.blocks.map(b => [b.id, b]));
    return r.ok.blocks.map(b => ({ c: b.content, parent: b.parent_id ? (by.get(b.parent_id) ? by.get(b.parent_id).content : "<parent not on page>") : null, pos: b.position }));
  };
  B.titles = async () => B.mine(await raw("list_pages", { limit: 100000 })).map(p => p.title);
  B.trashTitles = async () => B.mine(await raw("list_trash")).map(x => x.item_type + ":" + x.title + ":" + x.page_count).sort();
  B.hits = async (q, limit) => { const r = await B.t("search_blocks", { query: q, limit: limit || 50 }); return r.err ? r : r.ok.map(b => b.content).sort(); };
  B.backlinks = async pid => { const r = await B.t("get_backlinks", { pageId: pid }); if (r.err) return r; const out = []; for (const l of r.ok) { const b = await raw("get_block", { id: l.from_block }); out.push(b ? b.content : "<dangling from_block>"); } return out.sort(); };
  B.unlinked = async pid => { const r = await B.t("get_unlinked_references", { pageId: pid }); return r.err ? r : r.ok.map(b => b.content).sort(); };
  B.todo = async () => raw("get_pending_todo_count");
  B.exists = async titleOrId => !(await B.t("get_page_tree", { titleOrId })).err;
  return B;
}
const P = p => (p && typeof p === "object" ? { title: p.title, is_journal: !!p.is_journal, journal_date: p.journal_date || null, in_folder: !!p.folder_id } : p);
const OK = r => (r.err ? r : "ok");
const V = r => (r.err ? r : { ok: r.ok });           // value as-is
const PV = r => (r.err ? r : P(r.ok));
const BV = r => (r.err ? r : r.ok && typeof r.ok === "object" ? { c: r.ok.content, pos: r.ok.position, has_parent: !!r.ok.parent_id } : { ok: r.ok });
const flatFolders = (nodes, depth, out) => { for (const f of nodes || []) { out.push({ name: f.name, depth, pages: (f.pages || []).map(p => p.title), icon: f.icon || null, color: f.color || null }); flatFolders(f.children, depth + 1, out); } return out; };
const folderView = async B => { const t = await B.call("get_folder_tree"); return { folders: flatFolders(t.folders, 0, []).filter(f => f.name.includes(B.tag) || f.pages.some(p => p.includes(B.tag))), root_pages: B.mine(t.root_pages).map(p => p.title) }; };

const checks = [];
// impact: 3 = data loss / wrong data shown, 2 = user-visible behaviour, 1 = edge / error wording
const C = (id, area, op, inputs, impact, grep, run) => checks.push({ id, area, op, inputs, impact, grep, run });

