C("se02", "search", "search_blocks", "MIDDLE of a word (block has pre<tok>post, query <tok>)", 3, ["search\\("], async B => { const p = await B.page("P"); await B.blk(p.id, "the pre" + B.w("mid") + "post soup"); return B.hits(B.w("mid")); });
C("se03", "search", "search_blocks", "whole word, different case", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, "Mixed " + B.w("Token") + " here"); return B.hits(B.w("token").toUpperCase()); });
C("se04", "search", "search_blocks", "two words that are NOT adjacent in the block", 3, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("one") + " filler " + B.w("two")); return B.hits(B.w("one") + " " + B.w("two")); });
C("se05", "search", "search_blocks", "two words in REVERSED order", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("one") + " " + B.w("two")); return B.hits(B.w("two") + " " + B.w("one")); });
C("se06", "search", "search_blocks", "empty query and whitespace query (count capped at 5)", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("x")); const e = await B.t("search_blocks", { query: "", limit: 5 }); const w = await B.t("search_blocks", { query: "   ", limit: 5 }); return { empty: e.err ? e : e.ok.length > 0 ? "returns blocks" : "returns nothing", whitespace: w.err ? w : w.ok.length > 0 ? "returns blocks" : "returns nothing" }; });
for (const [i, q, label] of [[1, "-", "hyphenated token a-b"], [2, ":", "colon a:b"], [3, ".", "dotted a.b"], [4, "_", "underscore a_b"], [5, "/", "slash a/b"], [6, "@", "email-like a@b"]]) {
  C("se1" + i, "search", "search_blocks", label + " — query is the full punctuated string", 2, [], async B => { const p = await B.page("P"); const s = B.w("left") + q + B.w("right"); await B.blk(p.id, "see " + s + " ok"); return B.hits(s); });
}
for (const [i, q, label] of [[1, "\"", "a lone double quote"], [2, "*", "a lone asterisk"], [3, "(", "an open paren"], [4, "AND", "bare FTS operator AND"], [5, "NEAR(", "NEAR("], [6, "^", "caret"], [7, "'", "a single quote"], [8, "%", "percent sign"], [9, "-", "a lone hyphen"]]) {
  C("se2" + i, "search", "search_blocks", "query is " + label + " (does it throw?)", 2, [], async B => { const r = await B.t("search_blocks", { query: q, limit: 3 }); return r.err ? r : "no error"; });
}
C("se30", "search", "search_blocks", "query wrapped in [[ ]] finds the block with that wiki link", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, "see [[" + B.w("target") + "]] now"); return B.hits("[[" + B.w("target") + "]]"); });
C("se31", "search", "search_blocks", "#tag query", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, "note #" + B.w("tag") + " end"); return B.hits("#" + B.w("tag")); });
C("se32", "search", "search_blocks", "blocks of a TRASHED page", 3, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("trashed")); await B.call("trash_page", { id: p.id }); return B.hits(B.w("trashed")); });
C("se33", "search", "search_blocks", "blocks of an ARCHIVED page", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("archived")); await B.call("archive_page", { id: p.id }); return B.hits(B.w("archived")); });
C("se34", "search", "search_blocks", "limit=2 with 5 matches; and default limit", 1, [], async B => { const p = await B.page("P"); for (let i = 0; i < 5; i++) await B.blk(p.id, B.w("many") + " " + i); const r = await B.t("search_blocks", { query: B.w("many"), limit: 2 }); return r.err ? r : r.ok.length; });
C("se35", "search", "search_blocks", "CJK text (substring of a run) and accented word without the accent", 2, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("cjk") + " 東京都の天気"); await B.blk(p.id, B.w("acc") + " café"); const a = await B.t("search_blocks", { query: "京都", limit: 50 }); const c = await B.t("search_blocks", { query: "cafe", limit: 50 }); const mine = r => (r.err ? r : r.ok.filter(b => b.content.includes(B.w(""))).length); return { cjkSubstring: mine(a), unaccented: mine(c) }; });
C("se36", "search", "search_blocks", "after update: old text gone, new text found; after delete: gone", 3, [], async B => { const p = await B.page("P"); const a = await B.blk(p.id, B.w("old")); await B.call("update_block", { id: a.id, content: B.w("new") }); const o = await B.hits(B.w("old")), n = await B.hits(B.w("new")); await B.call("delete_block", { id: a.id }); return { old: o, new: n, afterDelete: await B.hits(B.w("new")) }; });
C("se37", "search", "search_blocks", "word that only appears in a page TITLE", 2, [], async B => { await B.call("create_page", { title: B.n("Title " + B.w("titleword")) }); return B.hits(B.w("titleword")); });
C("se38", "search", "search_blocks", "result ORDER for 3 matches created a, b, c", 1, [], async B => { const p = await B.page("P"); for (const c of ["a", "b", "c"]) await B.blk(p.id, B.w("ord") + " " + c); const r = await B.t("search_blocks", { query: B.w("ord"), limit: 10 }); return r.err ? r : r.ok.map(b => b.content.slice(-1)); });

C("se39", "search", "search_blocks(<block id>)", "look a block up by its ID (what PageView.handleBlockRefClick and ReviewPanel do)", 3, [], async B => { const p = await B.page("P"); const a = await B.blk(p.id, "target block"); const r = await B.t("search_blocks", { query: a.id, limit: 1 }); return r.err ? r : { foundTheBlock: r.ok.some(b => b.id === a.id), hits: r.ok.length }; });
C("se40", "search", "search_blocks", "stemming: block says \"running\", query \"run\" + unique token in the same block", 1, [], async B => { const p = await B.page("P"); await B.blk(p.id, B.w("stem") + " running"); const r = await B.t("search_blocks", { query: "run", limit: 100000 }); return r.err ? r : r.ok.filter(b => b.content.includes(B.w("stem"))).length; });

