C("ln01", "links", "get_backlinks", "block containing [[Target]] where Target exists", 3, ["getBacklinks", "Linked References", "backlink"], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Target") + "]]"); return B.backlinks(t.id); });
C("ln02", "links", "create_block with [[Missing]]", "link to a page that does not exist: is it auto-created?", 3, [], async B => { const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Missing") + "]]"); return { autoCreated: await B.exists(B.n("Missing")), titles: (await B.titles()).sort() }; });
C("ln03", "links", "rename_page (target)", "after renaming the link target: source block text + backlinks", 3, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Target") + "]]"); await B.call("rename_page", { id: t.id, newTitle: B.n("Renamed") }); return { sourceBlocks: (await B.tree(s.id)).map(x => x.c), backlinks: await B.backlinks(t.id) }; });
C("ln04", "links", "update_block / delete_block", "backlinks after the link text is removed, then re-added, then block deleted", 3, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); const b = await B.blk(s.id, "see [[" + B.n("Target") + "]]"); await B.call("update_block", { id: b.id, content: "no link" }); const removed = await B.backlinks(t.id); await B.call("update_block", { id: b.id, content: "again [[" + B.n("Target") + "]]" }); const readded = await B.backlinks(t.id); await B.call("delete_block", { id: b.id }); return { removed, readded, afterDelete: await B.backlinks(t.id) }; });
C("ln05", "links", "trash_page (source)", "backlinks from a page that is now in the trash", 2, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Target") + "]]"); await B.call("trash_page", { id: s.id }); return B.backlinks(t.id); });
C("ln06", "links", "get_unlinked_references", "plain-text mention of a page title (no brackets); linked mention excluded", 3, ["Unlinked", "getUnlinkedReferences"], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "plain mention of " + B.n("Target") + " here"); await B.blk(s.id, "linked [[" + B.n("Target") + "]]"); return B.unlinked(t.id); });
C("ln07", "links", "get_unlinked_references", "mention in different case; mention on the page itself", 1, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "lower " + B.n("Target").toLowerCase()); await B.blk(t.id, "self " + B.n("Target")); return B.unlinked(t.id); });
C("ln08", "links", "get_backlinks", "unknown page id", 1, [], async B => V(await B.t("get_backlinks", { pageId: GHOST })));
C("ln09", "links", "get_graph_data", "nodes/edges for Source -> Target", 2, ["getGraphData", "graph"], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Target") + "]]"); const g = await B.call("get_graph_data"); const nodes = B.mine(g.nodes); const ids = new Map(nodes.map(n => [n.id, n.title])); return { nodes: nodes.map(n => ({ title: n.title, block_count: n.block_count, link_count: n.link_count })).sort((a, b) => (a.title < b.title ? -1 : 1)), edges: g.edges.filter(e => ids.has(e.source) || ids.has(e.target)).map(e => ids.get(e.source) + " -> " + ids.get(e.target) + " x" + e.weight) }; });
C("ln10", "links", "add_alias / get_aliases", "alias, then a link written with the alias", 2, ["alias"], async B => { const t = await B.page("Target"); const s = await B.page("Source"); const add = OK(await B.t("add_alias", { pageId: t.id, alias: B.n("Nick") })); await B.blk(s.id, "see [[" + B.n("Nick") + "]]"); return { add, aliases: V(await B.t("get_aliases", { pageId: t.id })), backlinks: await B.backlinks(t.id), lookupByAlias: await B.exists(B.n("Nick")), titles: (await B.titles()).sort() }; });
C("ln11", "links", "get_backlinks", "two links to the same page in ONE block; link in a nested block", 1, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); const L = "[[" + B.n("Target") + "]]"; const a = await B.blk(s.id, L + " and " + L); await B.blk(s.id, "child " + L, a.id); return (await B.backlinks(t.id)).length; });
C("ln12", "links", "get_graph_stats", "deltas after 1 page + 2 blocks + 1 link", 1, [], async B => { const s0 = await B.call("get_graph_stats"); const t = await B.page("Target"); await B.blk(t.id, "a"); await B.blk(t.id, "self [[" + B.n("Target") + "]]"); const s1 = await B.call("get_graph_stats"); return { pages: s1.pages - s0.pages, blocks: s1.blocks - s0.blocks, links: s1.links - s0.links }; });

C("ln13", "links", "get_unlinked_references", "plain mention on a page that is now in the TRASH", 2, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "plain mention of " + B.n("Target") + " here"); await B.call("trash_page", { id: s.id }); return B.unlinked(t.id); });
C("ln14", "links", "get_graph_data", "is a TRASHED page still a graph node?", 2, [], async B => { const t = await B.page("Target"); const s = await B.page("Source"); await B.blk(s.id, "see [[" + B.n("Target") + "]]"); await B.call("trash_page", { id: s.id }); const g = await B.call("get_graph_data"); return B.mine(g.nodes).map(n => n.title).sort(); });

