const propView = r => (r.err ? r : r.ok.map(p => ({ key: p.key, value: p.value, value_type: p.value_type, entity_type: p.entity_type })).sort((a, b) => (a.key < b.key ? -1 : 1)));
C("pr01", "properties", "set_property / get_properties", "page property, default type", 2, ["setProperty", "getProperties"], async B => { const p = await B.page("P"); const r = await B.t("set_property", { entityId: p.id, entityType: "page", key: "status", value: "open" }); return { set: r.err ? r : { key: r.ok.key, value: r.ok.value, value_type: r.ok.value_type }, get: propView(await B.t("get_properties", { entityId: p.id })) }; });
C("pr02", "properties", "set_property x2", "same key twice: overwrite or duplicate?", 2, [], async B => { const p = await B.page("P"); await B.call("set_property", { entityId: p.id, entityType: "page", key: "k", value: "1" }); await B.call("set_property", { entityId: p.id, entityType: "page", key: "k", value: "2" }); return propView(await B.t("get_properties", { entityId: p.id })); });
C("pr03", "properties", "delete_property", "existing key, then the same key again, then on unknown entity", 1, [], async B => { const p = await B.page("P"); await B.call("set_property", { entityId: p.id, entityType: "page", key: "k", value: "1" }); return { first: V(await B.t("delete_property", { entityId: p.id, key: "k" })), second: V(await B.t("delete_property", { entityId: p.id, key: "k" })), ghost: V(await B.t("delete_property", { entityId: GHOST, key: "k" })), left: propView(await B.t("get_properties", { entityId: p.id })) }; });
C("pr04", "properties", "set_property", "value types number / date / boolean / made-up type", 2, [], async B => { const p = await B.page("P"); const out = {}; for (const [k, v, t] of [["n", "42", "number"], ["d", "2026-01-02", "date"], ["b", "true", "boolean"], ["x", "v", "made-up-type"], ["bad", "not-a-number", "number"]]) out[k] = OK(await B.t("set_property", { entityId: p.id, entityType: "page", key: k, value: v, valueType: t })); out.stored = propView(await B.t("get_properties", { entityId: p.id })); return out; });
C("pr05", "properties", "set_property", "entity that does not exist", 2, [], async B => { const r = await B.t("set_property", { entityId: GHOST, entityType: "block", key: B.w("k"), value: "v" }); return { set: OK(r) }; });
C("pr06", "properties", "set_property", "empty key; empty value", 1, [], async B => { const p = await B.page("P"); return { emptyKey: OK(await B.t("set_property", { entityId: p.id, entityType: "page", key: "", value: "v" })), emptyValue: OK(await B.t("set_property", { entityId: p.id, entityType: "page", key: "e", value: "" })), stored: propView(await B.t("get_properties", { entityId: p.id })) }; });
C("pr07", "properties", "get_inherited_properties", "child block inherits parent block + page properties?", 2, [], async B => { const p = await B.page("P"); const a = await B.blk(p.id, "a"); const a1 = await B.blk(p.id, "a1", a.id); await B.call("set_property", { entityId: p.id, entityType: "page", key: "from_page", value: "1" }); await B.call("set_property", { entityId: a.id, entityType: "block", key: "from_parent", value: "1" }); await B.call("set_property", { entityId: a1.id, entityType: "block", key: "own", value: "1" }); const r = await B.t("get_inherited_properties", { blockId: a1.id }); return r.err ? r : r.ok.map(x => x.key).sort(); });
C("pr08", "properties", "delete_block", "properties of a deleted block", 1, [], async B => { const p = await B.page("P"); const a = await B.blk(p.id, "a"); await B.call("set_property", { entityId: a.id, entityType: "block", key: "k", value: "v" }); await B.call("delete_block", { id: a.id }); return propView(await B.t("get_properties", { entityId: a.id })); });
C("pr09", "properties", "set_property", "entityType \"page\" given for a BLOCK id; unknown entityType", 1, [], async B => { const p = await B.page("P"); const a = await B.blk(p.id, "a"); return { wrongType: OK(await B.t("set_property", { entityId: a.id, entityType: "page", key: "k", value: "v" })), unknownType: OK(await B.t("set_property", { entityId: a.id, entityType: "banana", key: "k2", value: "v" })), stored: propView(await B.t("get_properties", { entityId: a.id })) }; });

