const favs = async B => B.mine(await B.call("list_favorites")).map(p => p.title);
C("fv01", "favorites", "add_favorite / list_favorites", "add two, list order", 2, ["addFavorite", "listFavorites", "favorite"], async B => { const a = await B.page("A"); const b = await B.page("B"); await B.call("add_favorite", { pageId: b.id }); await B.call("add_favorite", { pageId: a.id }); return favs(B); });
C("fv02", "favorites", "add_favorite x2", "same page twice", 2, [], async B => { const a = await B.page("A"); const r1 = OK(await B.t("add_favorite", { pageId: a.id })); const r2 = OK(await B.t("add_favorite", { pageId: a.id })); return { r1, r2, list: await favs(B) }; });
