C("fv05", "favorites", "add_favorite", "page id that does not exist", 2, [], async B => OK(await B.t("add_favorite", { pageId: GHOST })));
C("fv06", "favorites", "trash_page + restore", "is a favorite still a favorite after trash -> restore?", 2, [], async B => { const a = await B.page("A"); await B.call("add_favorite", { pageId: a.id }); await B.call("trash_page", { id: a.id }); const during = await favs(B); await B.call("restore_from_trash", { id: a.id, itemType: "page" }); return { whileTrashed: during, afterRestore: await favs(B) }; });
C("fv07", "favorites", "archive_page + unarchive", "is a favorite still a favorite after archive -> unarchive?", 2, [], async B => { const a = await B.page("A"); await B.call("add_favorite", { pageId: a.id }); await B.call("archive_page", { id: a.id }); const during = await favs(B); await B.call("unarchive_page", { id: a.id }); return { whileArchived: during, afterUnarchive: await favs(B) }; });
