C("fo06", "folders", "delete_folder", "folder with a SUBFOLDER that holds a page", 3, [], async B => { const f = await B.call("create_folder", { name: B.n("F") }); const g = await B.call("create_folder", { name: B.n("G"), parentId: f.id }); const a = await B.page("A"); await B.call("move_page_to_folder", { pageId: a.id, folderId: g.id }); const r = await B.t("delete_folder", { id: f.id }); return { ret: V(r), view: await folderView(B), pageExists: await B.exists(a.id), listed: await B.titles() }; });
C("fo07", "folders", "rename_folder", "existing; unknown id", 2, ["renameFolder"], async B => { const f = await B.call("create_folder", { name: B.n("F") }); const r = await B.t("rename_folder", { id: f.id, newName: B.n("F2") }); const g = await B.t("rename_folder", { id: GHOST, newName: B.n("Ghost") }); return { ok: r.err ? r : r.ok.name, ghost: g.err ? g : "returned a folder named " + g.ok.name, view: (await folderView(B)).folders.map(x => x.name) }; });
