// Expected values follow crates/minotes-core/src/repo/ai_suggestions.rs parse_pending_todo.
const TODO_LINES = [
  ["TODO write tests", 1], ["DOING write tests", 1], ["DONE write tests", 0], ["TODO", 0], ["TODO ", 0], ["TODOwrite", 0], ["todo write tests", 0], ["Todo write tests", 0],
  ["- [ ] task", 1], ["* [ ] task", 1], ["+ [ ] task", 1], ["- [x] task", 0], ["- [X] task", 0], ["-[ ] task", 0], ["- [ ]", 0], ["- [ ]task", 0], ["   - [ ] indented", 1], ["-   [ ]   spaced", 1], ["1. [ ] numbered", 0], ["[ ] bare box", 0], ["- [] no space in box", 0],
  ["TODO: colon form", 1], ["todo: lower colon", 1], ["Action: do it", 1], ["FOLLOW UP: call", 1], ["follow-up: call", 1], ["NEXT: step", 1], ["TODO:", 0], ["NOTE: not a todo", 0],
  ["{{todo:pending}} mirrored", 0], ["{{todo:doing}} mirrored", 0], ["﻿TODO with BOM", 1],
  ["TODO one\n- [ ] two\n- [x] three\nDOING four", 3], ["text before TODO in the middle", 0], ["> - [ ] quoted task", 0], ["## TODO heading", 0], ["- TODO bullet todo", 0], ["\tTODO tab-indented", 1],
];
TODO_LINES.forEach(([line, want], i) => {
  C("td" + String(i + 1).padStart(2, "0"), "todo", "get_pending_todo_count (delta)", JSON.stringify(line) + "  [rule says " + want + "]", 2, ["getPendingTodoCount", "TODO"], async B => { const p = await B.page("P"); const before = await B.todo(); await B.blk(p.id, line); return { delta: (await B.todo()) - before }; });
});
