C("rb08", "restore_blocks", "restore_blocks", "restored position collides with an existing sibling; page_id differs from parent's page", 2, [], async B => { const p = await B.page("P"); const q = await B.page("Q"); const a = await B.blk(p.id, "a"); const r1 = await B.t("restore_blocks", { blocks: [snap(p.id, uuid(), "same-pos", null, a.position)] }); const r2 = await B.t("restore_blocks", { blocks: [snap(q.id, uuid(), "cross-page-child", a.id, 1)] }); return { collide: OK(r1), crossPage: OK(r2), p: await B.tree(p.id), q: await B.tree(q.id) }; });

