C("ms06", "misc", "create_card / get_srs_stats", "flashcard from a block: total_cards delta, card block_id", 1, ["createCard", "flashcard"], async B => { const p = await B.page("P"); const a = await B.blk(p.id, "Q :: A"); const s0 = await B.call("get_srs_stats"); const r = await B.t("create_card", { blockId: a.id, cardType: "basic" }); const s1 = await B.call("get_srs_stats"); return { create: r.err ? r : { blockIdMatches: r.ok.block_id === a.id, state: r.ok.state }, totalDelta: s1.total_cards - s0.total_cards }; });
