// malformed (non-UUID) ids: does each command throw?
for (const [i, cmd, args] of [
  [1, "get_page_tree", { titleOrId: GARBAGE }], [2, "delete_page", { id: GARBAGE }], [3, "rename_page", { id: GARBAGE, newTitle: "x" }], [4, "create_block", { pageId: GARBAGE, content: "x" }],
  [5, "update_block", { id: GARBAGE, content: "x" }], [6, "delete_block", { id: GARBAGE }], [7, "get_block", { id: GARBAGE }], [8, "reorder_block", { id: GARBAGE, position: 1 }],
  [9, "get_backlinks", { pageId: GARBAGE }], [10, "get_unlinked_references", { pageId: GARBAGE }], [11, "get_properties", { entityId: GARBAGE }], [12, "add_favorite", { pageId: GARBAGE }],
  [13, "trash_page", { id: GARBAGE }], [14, "archive_page", { id: GARBAGE }], [15, "move_page_to_folder", { pageId: GARBAGE }], [16, "trash_folder", { id: GARBAGE }], [17, "restore_from_trash", { id: GARBAGE, itemType: "page" }],
]) C("er" + String(i).padStart(2, "0"), "errors", cmd, "malformed id \"" + GARBAGE + "\"", 1, [], async B => { const r = await B.t(cmd, args); return r.err ? r : "no error"; });
// missing required argument
for (const [i, cmd, args, what] of [[1, "create_page", {}, "no title"], [2, "create_block", { content: "x" }, "no pageId"], [3, "update_block", { id: GHOST }, "no content"], [4, "search_blocks", {}, "no query"], [5, "rename_page", { id: GHOST }, "no newTitle"]])
  C("ea" + String(i).padStart(2, "0"), "errors", cmd, "missing argument: " + what, 1, [], async B => { const r = await B.t(cmd, args); return r.err ? r : "no error"; });

// ───────────────────────── runner ─────────────────────────
const ID_RE = /\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b|\bmock-\d+-[0-9a-z]+\b/g;
const norm = v => {
  if (v === undefined || v === null) return null;
  if (typeof v === "string") { const s = v.replace(ID_RE, "<id>"); return s.length > 160 ? s.slice(0, 120) + "…(" + s.length + " chars)" : s; }
  if (Array.isArray(v)) return v.map(norm);
  if (typeof v === "object") { const o = {}; for (const k of Object.keys(v).sort()) { const n = norm(v[k]); if (n !== null) o[k] = n; } return o; }
  return v;
};
// For comparison only: an error is an error, whatever the wording.
const strip = v => {
  if (Array.isArray(v)) return v.map(strip);
  if (v && typeof v === "object") { if (typeof v.err === "string" && Object.keys(v).length === 1) return { err: true }; const o = {}; for (const k of Object.keys(v)) o[k] = strip(v[k]); return o; }
  return v;
};
const errs = (v, out) => { if (Array.isArray(v)) v.forEach(x => errs(x, out)); else if (v && typeof v === "object") { if (typeof v.err === "string" && Object.keys(v).length === 1) out.push(v.err); else Object.values(v).forEach(x => errs(x, out)); } return out; };

const only = window.__PARITY_ONLY__ ? new RegExp("^(" + window.__PARITY_ONLY__ + ")") : null;
const results = [];
for (const c of checks) {
  if (only && !only.test(c.id)) continue;
  const rec = { id: c.id, area: c.area, op: c.op, inputs: c.inputs, impact: c.impact, grep: c.grep };
  for (const name of ["mock", "real"]) {
    const t0 = performance.now();
    try { rec[name] = norm(await c.run(mkB(name, c.id))); }
    catch (e) { rec[name] = { HARNESS_ERROR: String((e && e.message) || e).replace(ID_RE, "<id>") }; }
    rec[name + "Ms"] = Math.round(performance.now() - t0);
  }
  const harness = [rec.mock, rec.real].some(r => r && typeof r === "object" && "HARNESS_ERROR" in r);
  rec.same = JSON.stringify(strip(rec.mock)) === JSON.stringify(strip(rec.real));
  // A scenario that could not finish on one side is still a divergence, but mark it.
  rec.incomplete = harness;
  rec.mockErrors = errs(rec.mock, []); rec.realErrors = errs(rec.real, []);
  results.push(rec);
}
return { ran: results.length, defined: checks.length, results };
